# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_mis_b import M
D=M+[['中古英语 mis- + demenure（行为、处事方式）','不当行为'],['英语 misdemeanor／misdemeanour','不当行为；一些法律体系中的较轻犯罪类别']]
BH=M+[['中古英语 misbehaven → 英语 misbehave','行为不当、不守规矩']]
WC=[
E('misconduct','名词英 /ˌmɪsˈkɒndʌkt/；美 /ˌmɪsˈkɑːndʌkt/','不当行为；失职；违规行为','行为越过了应遵守的职业、组织或道德界线。','mis- “不当” + conduct“行为”；历史也有管理不善的用法。',M+[['英语 mis- + conduct','不当的管理或行为'],['常用名词 misconduct','失职、违规或其他不当行为']],'misconduct 常出现在调查和纪律处分的语境：academic misconduct 是学术不端，professional misconduct 是职业失当。它比普通 mistake 更强调行为规范出了问题，但词本身不等于已经被判犯罪。','professional misconduct；academic misconduct；an allegation of misconduct。','misconduct 通常不可数；an instance of misconduct 才是在数一件事。mistake 可以只是无心算错，misconduct 常涉及应遵守的规则。',('The university investigated allegations of academic misconduct.','大学调查了有关学术不端的指控。'),('The report found evidence of serious misconduct by senior staff.','报告发现了高级员工严重失当行为的证据。'),sources=['https://www.etymonline.com/word/misconduct','https://en.wiktionary.org/wiki/misconduct']),
E('misdemeanor','美 /ˌmɪsdɪˈmiːnər/','轻罪；不当行为〔美式拼写〕','行为不当的一条正式用法，变成法律上与更严重犯罪相区别的类别。','mis- + 中古英语 demenure“行为”，后者关联 demeanor；不要拆成 mean“刻薄”加 -or。',D,'在美国新闻里 misdemeanor 常是具体法律分类，通常译为轻罪，与 felony 相对。它并不表示“完全不要紧”，也不能只凭这个词推算处罚。一般或文学语境里还可能只是指过失、不端行为。','a misdemeanor charge；be charged with a misdemeanor；a minor misdemeanor。','misdemeanor 是可数名词；misconduct 通常不可数，而且不必是法律分类。英式拼写常见 misdemeanour。',('The newspaper reported that he had been charged with a misdemeanor.','报纸报道说，他被指控犯有一项轻罪。'),('The article explains the distinction between a misdemeanor and a felony.','文章解释了轻罪与重罪的区别。'),sources=['https://www.etymonline.com/word/misdemeanor','https://www.merriam-webster.com/dictionary/misdemeanor']),
E('misdemeanour','英 /ˌmɪsdɪˈmiːnə/','不当行为；过失；轻罪〔英式拼写〕','同一个关于行为失当的词，在英式拼写里保留了 -our。','与 misdemeanor 同源；mis- + demeanor／demeanour，英式保留 u。',D+[['英式常见拼写 misdemeanour','根据语境指过失、不端行为或法律类别']],'misdemeanour 的拼写本身不告诉你文章采用哪国法律。日常英式表达里，minor misdemeanours 也可以略带轻松地说小过失。读历史或跨国报道时，要根据上下文判断是不是专门的法律类别。','a minor misdemeanour；past misdemeanours；a youthful misdemeanour。','misdemeanour 与 misdemeanor 是拼写差异；manner 是方式，demeanour 是举止，不能把本词理解成“没有礼貌”这一种固定意思。',('The teacher overlooked a few minor misdemeanours on the last day of term.','学期最后一天，老师没有计较几件小过失。'),('The biography describes several youthful misdemeanours with gentle humour.','这部传记以温和的幽默描述了几件年轻时的过失。'),sources=['https://www.etymonline.com/word/misdemeanor','https://dictionary.cambridge.org/dictionary/english/misdemeanour']),
E('misfortune','英 /ˌmɪsˈfɔːtʃuːn/；美 /ˌmɪsˈfɔːrtʃən/','不幸；厄运；不幸的事','事情落到自己头上，结果很糟，但不一定是自己做错了什么。','mis- “坏、不顺” + fortune“运气、命运”。这里 fortune 不应只按“财富”理解。',M+[['英语 mis- + fortune','坏运气、不顺的遭遇'],['misfortune','不幸，或一件具体的不幸事件']],'misfortune 可以说总体遭遇，也能说一次不幸。have the misfortune to do something 常是“偏偏不幸遇上”。mis- 在这里表示不好的结果，不能倒推出遭遇者有过错。','suffer misfortune；a series of misfortunes；have the misfortune to encounter something。','mistake 是错误；misfortune 是不幸。一个人可能没有犯错，仍遭到 misfortune。',('A series of misfortunes forced the family to move.','一连串的不幸迫使这家人搬迁。'),('I had the misfortune to lose my luggage on the first day of the trip.','旅行第一天，我就不幸丢了行李。'),sources=['https://www.etymonline.com/word/misfortune','https://en.wiktionary.org/wiki/misfortune']),
E('mishap','/ˈmɪshæp/','小事故；意外的不顺；不幸事件','原本按计划走着，突然出了一个岔子。','mis- “坏” + hap“运气、偶然发生的事”；hap 也能帮助联系 happen。',M+[['中古英语 mis- + hap','坏运气、不幸的偶发事件'],['英语 mishap','意外事故或不顺，常用于较小的岔子']],'mishap 常被用来淡化一次不严重的意外，比如打翻饮料或行李拿错。它并不从词义上保证事情绝不严重，但相比 disaster，语气通常轻得多。without mishap 就是一路顺利、没有出岔子。','a minor mishap；a travel mishap；without mishap。','mishap 侧重意外发生的事；misstep 更常突出某一步行动或决策出了错。',('Apart from a small mishap with the coffee machine, the morning went smoothly.','除了咖啡机出了点小状况，整个上午都很顺利。'),('The equipment arrived without mishap.','设备平安运到了，没有出岔子。'),sources=['https://www.etymonline.com/word/mishap','https://en.wiktionary.org/wiki/mishap']),
E('misstep','/ˌmɪsˈstep/，也读 /ˈmɪsstep/','失足；失策；错误的一步','脚下踩错一步的画面，延伸到做事时走了一步错棋。','mis- “错误” + step“步子”。两个 s 分别属于前后两部分。',M+[['英语 mis- + step','走错或踩错的一步'],['misstep','身体的失足；行动、判断上的失误']],'misstep 可以很具体地指踩错，也常用于策略或沟通：a political misstep 是政治上的失策。它把错误说成过程里的一步，暗示还可以回看哪里走偏、怎样调整。','a serious misstep；a strategic misstep；avoid another misstep。','misstep 通常着重一次错误行动；mishap 更像发生了一件不顺的意外，两者的关注点不同。',('The rushed announcement was a serious misstep.','那次仓促的公告是一次严重失策。'),('One misstep on the narrow path sent loose stones down the slope.','在那条窄路上踩错一步，就让松动的石头滚下了坡。'),sources=['https://en.wiktionary.org/wiki/misstep','https://www.merriam-webster.com/dictionary/misstep']),
E('misbehave','/ˌmɪsbɪˈheɪv/','行为不端；不守规矩；〔设备〕不正常运作','本来应按一定规矩表现，结果偏偏闹起了不合适的动作。','mis- “不当” + behave“表现、举止”。',BH,'misbehave 常说孩子在课堂上捣乱，也可以说成年人行为失当。口语把电脑或机器说成 misbehaving，是拟人地说它“不听话、出毛病”，不是真的责怪机器有道德问题。','misbehave in class；children who misbehave；a misbehaving printer。','misbehave 通常不直接接“某人”作宾语；mistreat someone 才是“虐待、恶劣对待某人”。',('The children started to misbehave after waiting for an hour.','等了一个小时后，孩子们开始不守规矩地闹了起来。'),('My printer has been misbehaving all morning.','我的打印机整个上午都在出毛病。'),sources=['https://en.wiktionary.org/wiki/misbehave','https://www.etymonline.com/word/misbehave']),
E('misbehavior','美 /ˌmɪsbɪˈheɪvjər/','不当行为；不守规矩〔美式拼写〕','不再说某人正在怎样做，而是把那种不合规矩的表现当成一件事来讨论。','mis- + behavior；与 misbehave 同族，behavior 是行为的名词。',M+[['英语 behavior：行为；加 mis-','行为表现不当'],['misbehavior','不当行为的统称']],'misbehavior 常用于学校、家庭或组织里对行为的评价。它一般不可数，谈一次具体行为可说 an instance of misbehavior。不是每个小失误都叫 misbehavior：算错题通常是 mistake，故意扰乱课堂才更合适。','disruptive misbehavior；address misbehavior；an instance of misbehavior。','misbehavior 是名词，misbehave 是动词。英式通常写 misbehaviour，含义基本相同。',('The teacher addressed the misbehavior without embarrassing the student.','老师处理了那个学生的不当行为，同时没有让他难堪。'),('The school records repeated instances of misbehavior.','学校会记录反复发生的不当行为。'),sources=['https://en.wiktionary.org/wiki/misbehavior','https://www.etymonline.com/word/misbehavior']),
E('misbehaviour','英 /ˌmɪsbɪˈheɪvjə/','不当行为；不守规矩〔英式拼写〕','还是对行为是否合适的评价，只是沿用 behaviour 的英式拼法。','mis- + behaviour；与 misbehavior 对应，-our 的 u 不带来新的意思。',M+[['英语 behaviour，加 mis-','不当的行为表现'],['英式 misbehaviour','不守规矩或其他失当行为']],'misbehaviour 在英国学校、家庭和公共生活的描述中很常用。它可以从小捣乱到更严重的失当，程度要由前面的修饰词和具体事情决定，不能一律翻成犯罪。','serious misbehaviour；classroom misbehaviour；deal with misbehaviour。','misbehaviour 与 misconduct 都可表示不当行为；misconduct 更常见于正式的职业、纪律调查语境。',('The coach spoke to the team about their misbehaviour on the bus.','教练就队员们在大巴上的不当行为和他们谈了话。'),('Clear routines can reduce classroom misbehaviour.','清晰的课堂常规可以减少不守规矩的行为。'),sources=['https://en.wiktionary.org/wiki/misbehaviour','https://dictionary.cambridge.org/dictionary/english/misbehaviour']),
E('misshapen','/ˌmɪsˈʃeɪpən/','变形的；形状不规则的','东西仍在那里，但形状没有长成或做成预期的样子。','mis- + shapen；shapen 是 shape 的旧过去分词形式。两个 s 是 mis- 与 shapen 相接。',M+[['中古英语 mis- + shapen','形状不对或变形的'],['英语 misshapen','不规则、畸形或走样的']],'misshapen 常描述物件或食物，如 misshapen potatoes 是长得不规整的土豆。词形保留了旧分词 shapen，现代普通过去式仍用 shaped，不要据此写 I shapen it。','a misshapen bowl；misshapen fruit；a misshapen lump。','misshapen 说形状；mismatched 说两个东西配不上。东西外形规整，也可能彼此 mismatched。',('The misshapen bowl still held water perfectly well.','那只形状不规整的碗仍然可以正常盛水。'),('The shop sells misshapen vegetables at a lower price.','这家店以较低价格出售外形不规整的蔬菜。'),sources=['https://en.wiktionary.org/wiki/misshapen','https://www.etymonline.com/word/misshapen']),
]
